/* global console, fetch */

/**
 * Refuse a package release whose pinned platform images are not public yet (PR #403 review).
 *
 * A project generated by `@indx-workspace/create@X.Y.Z` pulls the images
 * `packages/cli/src/release-images.json` names, at that file's `version`. Publishing the packages
 * before those images exist would ship a generator whose first `agent-workspace start` fails to
 * pull, so `.github/workflows/publish-packages.yml` runs this before `npm publish`. It asks the
 * registry anonymously — the same view a user's Docker daemon has — for each image's manifest.
 *
 *   node scripts/release/images-published.mjs --pin
 *
 * `--pin` writes the registry's `sha256` digest of every image into `release-images.json`
 * (`digests`, keyed like `images`), so the published CLI installs images by digest.
 */

import { readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';
import process from 'node:process';

const MANIFEST_TYPES = [
  'application/vnd.oci.image.index.v1+json',
  'application/vnd.docker.distribution.manifest.list.v2+json',
  'application/vnd.oci.image.manifest.v1+json',
  'application/vnd.docker.distribution.manifest.v2+json',
].join(', ');

/**
 * Every `<registry>/agent-workspace/<name>:<version>` reference the generator pins.
 *
 * It never answers with nothing: `images` must be a plain object naming at least one image, each
 * by a non-empty string, or the check would pass having checked no image at all.
 *
 * @param {string} root
 * @returns {Promise<string[]>}
 */
export async function pinnedImageReferences(root) {
  const file = path.join(root, 'packages', 'cli', 'src', 'release-images.json');
  const document = JSON.parse(await readFile(file, 'utf8'));
  const { registry, version, images } = document ?? {};
  if (typeof registry !== 'string' || typeof version !== 'string' || !isPlainObject(images)) {
    throw new Error(
      `RELEASE_IMAGES_INVALID: ${file} must have a string registry and version and an images object`,
    );
  }
  const names = Object.values(images);
  if (names.length === 0) {
    throw new Error(`RELEASE_IMAGES_INVALID: ${file} pins no image, so there is nothing to check`);
  }
  if (!names.every((name) => typeof name === 'string' && name !== '')) {
    throw new Error(
      `RELEASE_IMAGES_INVALID: ${file} names an image by something not a non-empty string`,
    );
  }
  return names.map((name) => `${registry}/agent-workspace/${name}:${version}`);
}

/**
 * @param {unknown} value
 * @returns {value is Record<string, unknown>}
 */
function isPlainObject(value) {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) return false;
  const prototype = Object.getPrototypeOf(value);
  return prototype === Object.prototype || prototype === null;
}

/**
 * Whether one reference resolves for an anonymous client, through the registry's token endpoint
 * and a manifest `HEAD` (the Docker registry HTTP API v2).
 *
 * @param {string} reference `<host>/<repository>:<tag>`
 * @param {typeof fetch} doFetch
 * @returns {Promise<{ ok: true, digest: string } | { ok: false, reason: string }>}
 */
export async function referenceResolvesAnonymously(reference, doFetch = fetch) {
  const slash = reference.indexOf('/');
  const colon = reference.lastIndexOf(':');
  if (slash <= 0 || colon <= slash) return { ok: false, reason: 'not <host>/<repository>:<tag>' };
  const host = reference.slice(0, slash);
  const repository = reference.slice(slash + 1, colon);
  const tag = reference.slice(colon + 1);
  const tokenResponse = await doFetch(
    `https://${host}/token?scope=${encodeURIComponent(`repository:${repository}:pull`)}`,
  );
  if (!tokenResponse.ok) {
    return { ok: false, reason: `anonymous token refused (HTTP ${String(tokenResponse.status)})` };
  }
  const { token } = /** @type {{ token?: unknown }} */ (await tokenResponse.json());
  if (typeof token !== 'string')
    return { ok: false, reason: 'the token endpoint returned no token' };
  const manifest = await doFetch(`https://${host}/v2/${repository}/manifests/${tag}`, {
    method: 'HEAD',
    headers: { authorization: `Bearer ${token}`, accept: MANIFEST_TYPES },
  });
  if (!manifest.ok) {
    return { ok: false, reason: `manifest not served (HTTP ${String(manifest.status)})` };
  }
  const digest = manifest.headers.get('docker-content-digest');
  return digest !== null && DIGEST.test(digest)
    ? { ok: true, digest }
    : { ok: false, reason: 'no content digest' };
}

const DIGEST = /^sha256:[0-9a-f]{64}$/u;

/**
 * Resolve every image of `release-images.json` and write its digest back as `digests`, keyed like
 * `images`. Nothing is written unless all images resolve.
 *
 * @param {string} root
 * @param {typeof fetch} [doFetch]
 * @returns {Promise<string[]>} the `<registry>/agent-workspace/<name>@<digest>` references
 */
export async function pinImageDigests(root, doFetch = fetch) {
  const references = await pinnedImageReferences(root);
  const file = path.join(root, 'packages', 'cli', 'src', 'release-images.json');
  const document = JSON.parse(await readFile(file, 'utf8'));
  const fields = Object.keys(document.images);
  /** @type {Record<string, string>} */
  const digests = {};
  const failures = [];
  for (const [index, reference] of references.entries()) {
    const field = fields[index];
    if (field === undefined)
      throw new Error(`PINNED_IMAGES_MISMATCH: no image field for ${reference}`);
    const outcome = await referenceResolvesAnonymously(reference, doFetch);
    if (outcome.ok) digests[field] = outcome.digest;
    else failures.push(`${reference}: ${outcome.reason}`);
  }
  if (failures.length > 0) {
    throw new Error(
      `PINNED_IMAGES_NOT_PUBLISHED: publish images-v<version> (and make each package public) before packages-v<version>:\n  ${failures.join('\n  ')}`,
    );
  }
  await writeFile(file, `${JSON.stringify({ ...document, digests }, null, 2)}\n`);
  const repository = `${document.registry}/agent-workspace`;
  return fields.map((field) => `${repository}/${document.images[field]}@${digests[field]}`);
}

if (process.argv[1] && path.resolve(process.argv[1]) === path.resolve(import.meta.filename)) {
  try {
    if (!process.argv.includes('--pin')) throw new Error('usage: images-published.mjs --pin');
    const pinned = await pinImageDigests(process.cwd());
    const fields = Object.keys(
      JSON.parse(await readFile(path.join('packages', 'cli', 'src', 'release-images.json'), 'utf8'))
        .images,
    );
    for (const [index, reference] of pinned.entries()) console.log(`${fields[index]} ${reference}`);
  } catch (error) {
    console.error(error instanceof Error ? error.message : String(error));
    process.exitCode = 1;
  }
}
